typedef unsigned long long big_int;

class string_buf
{
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

public:
  inline int get_ref()
  {
    return ref_count;
  }

  friend class stringx;
};

class stringx
{
  char *chars;
  string_buf *my_buf;

public:
  void fork_data(int new_len = -1);

  inline char &operator[](int i)
  {
    lock();
    if (i < 0)
      i += length();
    return chars[i];
  }

  inline void lock()
  {
    if (my_buf->get_ref() > 1)
      fork_data();
  }

  inline int size() const
  {
    return my_buf->char_length;
  }

  inline int length() const
  {
    return size();
  }
};

enum {
  GT_REPLACE_ENDLINE,
  GT_REPLACE_LAST
};

enum {
  GT_REPLACE_FR_1,
  GT_REPLACE_FR_2,
  GT_REPLACE_FR_3,
  GT_REPLACE_FR_4,
  GT_REPLACE_FR_5,
  GT_REPLACE_FR_6,
  GT_REPLACE_FR_7,
  GT_REPLACE_FR_8,
  GT_REPLACE_FR_9,
  GT_REPLACE_FR_10,
  GT_REPLACE_FR_11,
  GT_REPLACE_FR_12,
  GT_REPLACE_FR_13,
  GT_REPLACE_FR_LAST
};

enum {
  GT_REPLACE_GE_1,
  GT_REPLACE_GE_2,
  GT_REPLACE_GE_3,
  GT_REPLACE_GE_4,
  GT_REPLACE_GE_5,
  GT_REPLACE_GE_LAST
};

enum {
  LANGUAGE_ENGLISH,
  LANGUAGE_PIG_LATIN,
  LANGUAGE_FRENCH,
  LANGUAGE_GERMAN,
  LANGUAGE_LAST
};

extern char ksGlobalReplaceArray[][2];
extern char ksGlobalReplaceFRArray[][2];
extern char ksGlobalReplaceGEArray[][2];
extern int ksGlobalTextLanguage;

class TextString
{
public:
  static void MakeReplacements(stringx& text);
};

void TextString::MakeReplacements(stringx& text)
{
	for(int i=0; i<text.size(); i++)
	{
		for(int j=0; j<GT_REPLACE_LAST; j++)
		{
			if(text[i] == ksGlobalReplaceArray[j][0])
				text[i] = ksGlobalReplaceArray[j][1];
		}

		// make french & german replacements, if necessary
		// (they share a few letters)
		if(ksGlobalTextLanguage == LANGUAGE_FRENCH || ksGlobalTextLanguage == LANGUAGE_GERMAN)
		{
			for(int j=0; j<GT_REPLACE_FR_LAST; j++)
			{
				if(text[i] == ksGlobalReplaceFRArray[j][0])
					text[i] = ksGlobalReplaceFRArray[j][1];
			}

			for(int j=0; j<GT_REPLACE_GE_LAST; j++)
			{
				if(text[i] == ksGlobalReplaceGEArray[j][0])
					text[i] = ksGlobalReplaceGEArray[j][1];
			}
		}
	}
}
